{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "606 deaths/missing along the Mediterranean by end-February 2026 indicates an unusually high early-year pace, increasing the odds of reaching 1,000 by May if the trend persists.",
    "Historical annual Mediterranean tolls (~2,100–2,450) provide context that a 1,000-by-May threshold is plausible within a high-trajectory year, though not guaranteed.",
    "Reporting lags and potential revisions could push totals higher, while weather/seasonality and SAR capacity add both upside and downside dynamics.",
    "Bayesian updating from the February pace and contemporaneous factors yields a calibrated posterior probability of 0.95 for hitting 1,000 deaths by May 2026."
  ],
  "confidence": "high",
  "narrative": "Starting from a central Mediterranean anchor, the exceptionally high early-2026 death pace (606 by February) updates the probability upward toward 1,000 deaths by May, even as reporting lags and policy/SAR dynamics inject uncertainty. The posterior suggests a high likelihood, calibrated around 95%.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class is IOM Missing Migrants Project central Mediterranean fatalities; anchor probability 0.65 reflects baseline with substantial headroom for updates from the unusually high February pace."
    },
    "factor_updates": [
      {
        "factor": "Pace carryover from February 2026 (606 deaths by 28 February)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Observed front-loaded mortality rate far above long-run monthly averages; if sustained, it elevates the odds of reaching 1,000 by May."
      },
      {
        "factor": "Weather events driving mortality (early 2026 storms, sea conditions)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Unfavorable conditions can increase crossing fatalities, reinforcing the up‑update signal."
      },
      {
        "factor": "Reporting lag and data gaps in Missing Migrants records",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Delayed or revised counts can raise the eventual total beyond observed February counts."
      },
      {
        "factor": "Policy responses and SAR capacity potentially reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter policies and enhanced rescue capacity could dampen fatalities, offsetting some upward signals."
      },
      {
        "factor": "Seasonal/dynamic uncertainty in later months (March–May variability)",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Month-to-month variability introduces uncertainty; cannot be assumed monotonic."
      }
    ],
    "synthesis_rationale": "Starting from a mid-range anchor (0.65), the dominant updates (front-loaded 606 deaths by Feb, plausibly harsher spring conditions) pull the probability upward toward 0.95, while the offsetting updates (policy/SAR dampening, reporting lags, and March–May variability) temper the rise. The final posterior reflects a calibrated balance with strong evidence for a high-likelihood outcome, acknowledging residual uncertainty and potential correlations among factors."
  }
}

{
  "probability": 0.95,
  "range_low": 0.85,
  "range_high": 0.99,
  "summary": [
    "February 2026 count of 606 Mediterranean deaths/missing implies a high front-loaded mortality pace; continuation through March–April could push the May total past 1,000.",
    "Historical Mediterranean tolls are typically around 2,100–2,450 per year, so reaching 1,000 by May would be plausible within annual volatility, albeit contingent on ongoing conditions.",
    "Uncertainties include reporting lags, weather-driven crossing conditions, and policy/SAR responses that could dampen or amplify deaths."
  ],
  "confidence": "high",
  "narrative": "Observational data through February 2026 show an unusually high pace that, if sustained, makes reaching 1,000 deaths by May plausible. While historical annual totals imply such a pace is not out of the question, there are still significant uncertainties around reporting and external factors that could alter the trajectory.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Baseline reference class uses IOM Missing Migrants Project annual Mediterranean fatalities (~2,100–2,450 per year) with an observed 606 deaths/missing by end-February 2026, suggesting a high but not guaranteed carryover into May."
    },
    "factor_updates": [
      {
        "factor": "Pace carryover from February 2026 (606 deaths by 28 February) into March-April-May",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "The 606 figure by February represents a record-fast start to a year; if this pace persists, the accumulated deaths by May could exceed 1,000 (AP News; Guardian; Reuters)."
      },
      {
        "factor": "Historical baseline and high annual volatility of Mediterranean toll",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual totals around 2,100–2,450 mean that 1,000 by May would be plausible within a high-early-year trajectory, though not certain."
      },
      {
        "factor": "Data reporting lags and potential undercounting in 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Incomplete or delayed reporting can imply higher eventual counts, nudging the May total upward."
      },
      {
        "factor": "Seasonal/weather conditions influencing crossings in spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Improved spring conditions can increase crossings and fatalities, contributing to a higher count by May."
      },
      {
        "factor": "Policy/SAR capacity and response reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter policies or expanded rescue capacity could reduce fatalities, offsetting gains from pace; introduces downward pressure on the total."
      }
    ],
    "synthesis_rationale": "Starting from a moderate anchor, the large positive updates from frontline February data tilt the posterior toward a high probability of crossing 1,000 by May. However, correlated factors (pace, weather, and reporting) amplify each other, while SAR/policy responses provide a countervailing, downward pressure. The combination yields a tight, high-calibration posterior around 0.95, with uncertainty mainly from potential revisions to the February count and unforeseen policy or weather shifts."
  }
}

